// codegen/tests/bridge_test.cpp
//
// Value-ABI bridge ① (DESIGN.md §6a): the opaque C ABI dispatches to real
// nk builtins by name, with box/unbox round-tripping scalars and arrays.
// Exercises the C ABI directly (the generated code will use it via the
// prelude RAII wrapper, brick ②).

#include "numkit_codegen_rt.h"

#include "numkit_codegen_test_paths.h"  // NUMKIT_SAMPLE_PLUGIN_PATH (generated by CMake)

#include <gtest/gtest.h>

#include <cmath>
#include <cstdio>

TEST(Bridge, ScalarBuiltin)
{
    numkit_val x = numkit_box_scalar(0.0);
    numkit_val r = numkit_call("sin", &x, 1, 1, nullptr, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 0.0);  // sin(0) = 0
    numkit_release(x);
    numkit_release(r);
}

TEST(Bridge, ScalarBuiltinNonzero)
{
    numkit_val x = numkit_box_scalar(1.0);
    numkit_val r = numkit_call("exp", &x, 1, 1, nullptr, nullptr);
    EXPECT_NEAR(numkit_unbox_scalar(r), std::exp(1.0), 1e-12);
    numkit_release(x);
    numkit_release(r);
}

TEST(Bridge, ArrayBuiltinSum)
{
    const double in[3] = {1.0, 2.0, 3.0};
    numkit_val       a     = numkit_box_array(in, 3);
    EXPECT_EQ(numkit_numel(a), 3u);
    numkit_val r = numkit_call("sum", &a, 1, 1, nullptr, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 6.0);
    numkit_release(a);
    numkit_release(r);
}

TEST(Bridge, ArrayBuiltinSortRoundTrip)
{
    const double in[4] = {3.0, 1.0, 4.0, 2.0};
    numkit_val       a     = numkit_box_array(in, 4);
    numkit_val       s     = numkit_call("sort", &a, 1, 1, nullptr, nullptr);
    ASSERT_EQ(numkit_numel(s), 4u);
    double out[4] = {0, 0, 0, 0};
    numkit_unbox_array(s, out, 4);
    EXPECT_DOUBLE_EQ(out[0], 1.0);
    EXPECT_DOUBLE_EQ(out[1], 2.0);
    EXPECT_DOUBLE_EQ(out[2], 3.0);
    EXPECT_DOUBLE_EQ(out[3], 4.0);
    numkit_release(a);
    numkit_release(s);
}

// G3: a CHAR-array result (num2str) unboxes its code units into a uint16 buffer (the codegen's
// char width). The runtime owns the formatting; this exercises numkit_unbox_char_array directly.
TEST(Bridge, Num2strCharUnbox)
{
    numkit_val x = numkit_box_scalar(42.0);
    numkit_val r = numkit_call("num2str", &x, 1, 1, nullptr, nullptr);  // '42'
    ASSERT_NE(r, nullptr);
    ASSERT_EQ(numkit_numel(r), 2u);
    uint16_t out[2] = {0, 0};
    numkit_unbox_char_array(r, out, 2);
    EXPECT_EQ(out[0], static_cast<uint16_t>('4'));  // 52
    EXPECT_EQ(out[1], static_cast<uint16_t>('2'));  // 50
    numkit_release(x);
    numkit_release(r);
}

// CX4a: complex array box/unbox round-trip (interleaved re,im). Also drives a
// bridged complex builtin (fft) so a complex RESULT is unboxed via the new
// path. (The codegen complex bridge, CX4b, builds on these C-ABI primitives.)
TEST(Bridge, ComplexArrayRoundTrip)
{
    const double in[6] = {1, 2, 3, 4, 5, 6};  // 1+2i, 3+4i, 5+6i
    numkit_val       a     = numkit_box_complex_array(in, 3);
    ASSERT_NE(a, nullptr);
    ASSERT_EQ(numkit_numel(a), 3u);
    double out[6] = {0, 0, 0, 0, 0, 0};
    numkit_unbox_complex_array(a, out, 3);
    for (int i = 0; i < 6; ++i) EXPECT_DOUBLE_EQ(out[i], in[i]);  // exact round-trip
    numkit_release(a);
}

TEST(Bridge, ComplexResultFromBridgedFft)
{
    // fft of a real signal returns a COMPLEX array; unbox via the complex path.
    const double sig[4] = {1.0, 2.0, 3.0, 4.0};
    numkit_val       x      = numkit_box_array(sig, 4);
    numkit_val       y      = numkit_call("fft", &x, 1, 1, nullptr, nullptr);
    ASSERT_NE(y, nullptr);
    ASSERT_EQ(numkit_numel(y), 4u);
    double out[8] = {0};  // 4 complex
    numkit_unbox_complex_array(y, out, 4);
    // DC bin = sum = 10 (imag 0); the transform is non-trivial elsewhere.
    EXPECT_DOUBLE_EQ(out[0], 10.0);
    EXPECT_DOUBLE_EQ(out[1], 0.0);
    numkit_release(x);
    numkit_release(y);
}

// A runtime error inside a bridged call must be TRANSLATED (numkit_error),
// never thrown across the extern "C" boundary (that is UB). The call
// returns null and the process does not crash.
TEST(Bridge, ErrorTranslatedNotThrown)
{
    numkit_val   x = numkit_box_scalar(1.0);
    numkit_error err;
    err.code = 0;
    numkit_val r = numkit_call("a_function_that_does_not_exist_zzz", &x, 1, 1, nullptr, &err);
    EXPECT_EQ(r, nullptr);            // failed cleanly
    EXPECT_NE(err.code, 0);           // error reported
    EXPECT_NE(err.message[0], '\0');  // with a message
    numkit_release(x);
}

// Hardening (self-review): a null argument handle is REPORTED, never
// dereferenced (a null deref is UB the try/catch cannot save).
TEST(Bridge, NullArgHandleReportsError)
{
    numkit_val   args[1] = {nullptr};
    numkit_error err;
    err.code = 0;
    numkit_val r = numkit_call("sin", args, 1, 1, nullptr, &err);
    EXPECT_EQ(r, nullptr);
    EXPECT_NE(err.code, 0);
}

// Hardening (self-review): boxing a null array pointer fails cleanly; a
// zero-length array (null ok, nothing to read) is a valid empty handle.
TEST(Bridge, BoxArrayNullPointer)
{
    EXPECT_EQ(numkit_box_array(nullptr, 3), nullptr);
    numkit_val z = numkit_box_array(nullptr, 0);
    EXPECT_EQ(numkit_numel(z), 0u);
    numkit_release(z);
}

// ---- A1: Dynamic-tier value operations (DESIGN.md §10 C1) ------------------
// The value-level operator + truthiness primitives the generated Dynamic tier
// (A2+) uses for operands whose type the codegen inference could not pin down.
// Overload-aware and identical to the interpreter (they route through the same
// Engine dispatch the TreeWalker / VM use).

TEST(Bridge, BinOpScalarArithmetic)
{
    numkit_val a = numkit_box_scalar(3.0);
    numkit_val b = numkit_box_scalar(4.0);
    numkit_val s = numkit_binop("+", a, b, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(s), 7.0);
    numkit_val d = numkit_binop("-", a, b, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(d), -1.0);
    numkit_val p = numkit_binop("*", a, b, nullptr);  // scalar "*" == mtimes
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(p), 12.0);
    numkit_release(a);
    numkit_release(b);
    numkit_release(s);
    numkit_release(d);
    numkit_release(p);
}

TEST(Bridge, BinOpArrayElementwise)
{
    const double xa[3] = {1, 2, 3};
    const double xb[3] = {10, 20, 30};
    numkit_val       a     = numkit_box_array(xa, 3);
    numkit_val       b     = numkit_box_array(xb, 3);
    numkit_val       s     = numkit_binop(".*", a, b, nullptr);  // elementwise multiply
    ASSERT_EQ(numkit_numel(s), 3u);
    double out[3] = {0, 0, 0};
    numkit_unbox_array(s, out, 3);
    EXPECT_DOUBLE_EQ(out[0], 10.0);
    EXPECT_DOUBLE_EQ(out[1], 40.0);
    EXPECT_DOUBLE_EQ(out[2], 90.0);
    numkit_release(a);
    numkit_release(b);
    numkit_release(s);
}

TEST(Bridge, BinOpComparisonIsLogical)
{
    numkit_val a  = numkit_box_scalar(3.0);
    numkit_val b  = numkit_box_scalar(4.0);
    numkit_val lt = numkit_binop("<", a, b, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(lt), 1.0);  // 3 < 4 -> true
    numkit_val gt = numkit_binop(">", a, b, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(gt), 0.0);
    numkit_release(a);
    numkit_release(b);
    numkit_release(lt);
    numkit_release(gt);
}

TEST(Bridge, UnOpNegateAndNot)
{
    numkit_val a = numkit_box_scalar(5.0);
    numkit_val n = numkit_unop("-", a, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(n), -5.0);
    numkit_val z = numkit_box_scalar(0.0);
    numkit_val t = numkit_unop("~", z, nullptr);  // ~0 -> true
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(t), 1.0);
    numkit_release(a);
    numkit_release(n);
    numkit_release(z);
    numkit_release(t);
}

TEST(Bridge, TruthScalarAndArray)
{
    numkit_val t = numkit_box_scalar(1.0);
    numkit_val f = numkit_box_scalar(0.0);
    EXPECT_EQ(numkit_truth(t, nullptr), 1);
    EXPECT_EQ(numkit_truth(f, nullptr), 0);
    numkit_release(t);
    numkit_release(f);
    const double allnz[3] = {1, 2, 3};
    const double hasz[3]  = {1, 0, 3};
    numkit_val       a        = numkit_box_array(allnz, 3);
    numkit_val       z        = numkit_box_array(hasz, 3);
    EXPECT_EQ(numkit_truth(a, nullptr), 1);  // every element non-zero -> true
    EXPECT_EQ(numkit_truth(z, nullptr), 0);  // a zero element -> false
    numkit_release(a);
    numkit_release(z);
}

// A nk error in a value op (dimension mismatch) is TRANSLATED via numkit_error,
// never thrown across the C boundary; the call returns null and is leak-free.
TEST(Bridge, BinOpErrorTranslatedNoLeak)
{
    const long long before = numkit_debug_live_handles();
    const double     xa[2] = {1, 2};
    const double     xb[3] = {1, 2, 3};
    numkit_val           a     = numkit_box_array(xa, 2);
    numkit_val           b     = numkit_box_array(xb, 3);
    numkit_error         err;
    err.code     = 0;
    numkit_val r     = numkit_binop("+", a, b, &err);  // incompatible dims
    EXPECT_EQ(r, nullptr);
    EXPECT_NE(err.code, 0);
    EXPECT_NE(err.message[0], '\0');
    numkit_release(a);
    numkit_release(b);
    EXPECT_EQ(numkit_debug_live_handles(), before);  // no handle leaked on the error path
}

// numkit_index resolves value(subs) the way the interpreter does — `value(subs)` is
// index/call-AMBIGUOUS, so an array is INDEXED but a function handle is CALLED.
// A Dynamic value thus behaves identically whatever it is at runtime (A4 soundness).
TEST(Bridge, IndexArrayElement)
{
    const double xa[4] = {10, 20, 30, 40};
    numkit_val       a     = numkit_box_array(xa, 4);
    numkit_val       i     = numkit_box_scalar(3.0);  // 1-based
    numkit_val       r     = numkit_index(a, &i, 1, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 30.0);  // a(3)
    numkit_release(a);
    numkit_release(i);
    numkit_release(r);
}

TEST(Bridge, IndexFunctionHandleCalls)
{
    // value(subs) on a function handle is a CALL, not indexing — the crux of the
    // index/call ambiguity. sin(0) = 0 (NOT "element 0 of a handle").
    numkit_val h = numkit_eval("@sin", nullptr);
    ASSERT_NE(h, nullptr);
    numkit_val arg = numkit_box_scalar(0.0);
    numkit_val r   = numkit_index(h, &arg, 1, nullptr);
    ASSERT_NE(r, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 0.0);
    numkit_release(h);
    numkit_release(arg);
    numkit_release(r);
}

TEST(Bridge, IndexVectorSubscriptSubArray)
{
    const double xa[4] = {10, 20, 30, 40};
    numkit_val       a     = numkit_box_array(xa, 4);
    const double ia[2] = {2, 4};
    numkit_val       i     = numkit_box_array(ia, 2);  // a([2 4]) -> [20 40]
    numkit_val       r     = numkit_index(a, &i, 1, nullptr);
    ASSERT_EQ(numkit_numel(r), 2u);
    double out[2] = {0, 0};
    numkit_unbox_array(r, out, 2);
    EXPECT_DOUBLE_EQ(out[0], 20.0);
    EXPECT_DOUBLE_EQ(out[1], 40.0);
    numkit_release(a);
    numkit_release(i);
    numkit_release(r);
}

TEST(Bridge, IndexMatrixTwoSubscripts)
{
    // 2-D A(i,j) via two subscripts — the multi-subscript path resolves each
    // subscript against its dim and reads via indexGetND (which delegates to
    // indexGet2D), exactly like the interpreter.
    const double m[4]    = {10, 20, 30, 40};  // column-major 2x2: [10 30; 20 40]
    numkit_val       a       = numkit_box_matrix(m, 2, 2);
    numkit_val       subs[2] = {numkit_box_scalar(2.0), numkit_box_scalar(1.0)};  // A(2,1) = 20
    numkit_val       r       = numkit_index(a, subs, 2, nullptr);
    ASSERT_NE(r, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 20.0);
    numkit_release(a);
    numkit_release(subs[0]);
    numkit_release(subs[1]);
    numkit_release(r);
}

TEST(Bridge, IndexOutOfBoundsReported)
{
    const double xa[2] = {1, 2};
    numkit_val       a     = numkit_box_array(xa, 2);
    numkit_val       i     = numkit_box_scalar(5.0);  // out of bounds
    numkit_error     err;
    err.code   = 0;
    numkit_val r   = numkit_index(a, &i, 1, &err);
    EXPECT_EQ(r, nullptr);
    EXPECT_NE(err.code, 0);  // bounds error translated, not UB
    numkit_release(a);
    numkit_release(i);
}

// Shape-preserving boxers for a Dynamic ARRAY operand (column-major). Round-trip
// box -> numel -> unbox (flat) confirms the shape + values survive.
TEST(Bridge, BoxMatrixRoundTrip)
{
    const double m[6] = {1, 4, 2, 5, 3, 6};  // 2x3, column-major
    numkit_val       a    = numkit_box_matrix(m, 2, 3);
    ASSERT_NE(a, nullptr);
    EXPECT_EQ(numkit_numel(a), 6u);
    double out[6] = {0, 0, 0, 0, 0, 0};
    numkit_unbox_array(a, out, 6);
    for (int i = 0; i < 6; ++i) EXPECT_DOUBLE_EQ(out[i], m[i]);
    numkit_release(a);
}

TEST(Bridge, BoxArrayNdRoundTrip)
{
    const std::size_t dims[3] = {2, 2, 2};
    const double      v[8]    = {1, 2, 3, 4, 5, 6, 7, 8};  // 2x2x2, column-major
    numkit_val            a       = numkit_box_array_nd(v, dims, 3);
    ASSERT_NE(a, nullptr);
    EXPECT_EQ(numkit_numel(a), 8u);
    double out[8] = {0, 0, 0, 0, 0, 0, 0, 0};
    numkit_unbox_array(a, out, 8);
    for (int i = 0; i < 8; ++i) EXPECT_DOUBLE_EQ(out[i], v[i]);
    numkit_release(a);
}

// ---- Plugin / extension ABI (DESIGN.md §6b) --------------------------------
// A plugin PROVIDES functions with the numkit_fn signature (the mirror of
// numkit_call). Once registered, they resolve from nk source / numkit_call /
// embedding exactly like a builtin — proving the register -> resolve ->
// dispatch loop with no core change (uses Engine::registerFunction).

// A plugin function: doubles its scalar argument.
static numkit_val numkit_test_double(const numkit_val *args, size_t nargs, size_t nargout,
                             numkit_val *extra_outs, numkit_error *err)
{
    (void)nargs;
    (void)nargout;
    (void)extra_outs;
    (void)err;
    return numkit_box_scalar(numkit_unbox_scalar(args[0]) * 2.0);
}

TEST(Plugin, RegisterAndCall)
{
    ASSERT_EQ(numkit_register_fn("numkit_test_double", numkit_test_double), 0);
    numkit_val x = numkit_box_scalar(21.0);
    numkit_val r = numkit_call("numkit_test_double", &x, 1, 1, nullptr, nullptr);
    ASSERT_NE(r, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 42.0);
    numkit_release(x);
    numkit_release(r);
}

// A two-output plugin function: [q, r] = divmod(a, b).
static numkit_val numkit_test_divmod(const numkit_val *args, size_t nargs, size_t nargout,
                             numkit_val *extra_outs, numkit_error *err)
{
    (void)nargs;
    (void)err;
    const double a = numkit_unbox_scalar(args[0]);
    const double b = numkit_unbox_scalar(args[1]);
    if (nargout >= 2 && extra_outs) extra_outs[0] = numkit_box_scalar(std::fmod(a, b));
    return numkit_box_scalar(std::trunc(a / b));  // quotient (first output)
}

TEST(Plugin, RegisterMultiOutput)
{
    ASSERT_EQ(numkit_register_fn("numkit_test_divmod", numkit_test_divmod), 0);
    numkit_val args[2] = {numkit_box_scalar(17.0), numkit_box_scalar(5.0)};
    numkit_val extra[1] = {nullptr};
    numkit_val q = numkit_call("numkit_test_divmod", args, 2, 2, extra, nullptr);
    ASSERT_NE(q, nullptr);
    ASSERT_NE(extra[0], nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(q), 3.0);         // 17 div 5
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(extra[0]), 2.0);  // 17 mod 5
    numkit_release(args[0]);
    numkit_release(args[1]);
    numkit_release(q);
    numkit_release(extra[0]);
}

// A plugin function that reports an error must surface as numkit_error at the
// call site, never crash the process.
static numkit_val numkit_test_raise(const numkit_val *args, size_t nargs, size_t nargout,
                            numkit_val *extra_outs, numkit_error *err)
{
    (void)args;
    (void)nargs;
    (void)nargout;
    (void)extra_outs;
    if (err) {
        err->code = 7;
        std::snprintf(err->message, sizeof(err->message), "plugin says no");
    }
    return nullptr;
}

TEST(Plugin, ErrorPropagates)
{
    ASSERT_EQ(numkit_register_fn("numkit_test_raise", numkit_test_raise), 0);
    numkit_val  x = numkit_box_scalar(1.0);
    numkit_error e;
    e.code = 0;
    numkit_val r = numkit_call("numkit_test_raise", &x, 1, 1, nullptr, &e);
    EXPECT_EQ(r, nullptr);            // failed cleanly
    EXPECT_NE(e.code, 0);             // error reported across the bridge
    EXPECT_NE(e.message[0], '\0');    // with a message
    numkit_release(x);
}

// Bad arguments to registration are rejected, not crashed.
TEST(Plugin, RegisterRejectsNull)
{
    EXPECT_NE(numkit_register_fn(nullptr, numkit_test_double), 0);
    EXPECT_NE(numkit_register_fn("numkit_test_null", nullptr), 0);
}

// The full loadable-plugin path: dlopen a standalone shared library, run its
// ABI-version check + registration hook, then call its registered function
// through the same dispatch as a builtin. This exercises the real plugin
// boundary end to end (no in-process shortcut).
TEST(Plugin, LoadSharedLibraryAndCall)
{
    numkit_error err;
    err.code   = 0;
    const int rc = numkit_load_plugin(NUMKIT_SAMPLE_PLUGIN_PATH, &err);
    ASSERT_EQ(rc, 0) << "load failed: " << err.message << " (path: " << NUMKIT_SAMPLE_PLUGIN_PATH << ")";

    numkit_val x = numkit_box_scalar(7.0);
    numkit_val r = numkit_call("numkit_sample_triple", &x, 1, 1, nullptr, nullptr);
    ASSERT_NE(r, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 21.0);  // 7 * 3
    numkit_release(x);
    numkit_release(r);
}

// A missing / bad plugin path fails cleanly with an error, never crashes.
TEST(Plugin, LoadMissingFileFails)
{
    numkit_error err;
    err.code     = 0;
    const int rc = numkit_load_plugin("definitely_not_a_real_plugin_zzz.dll", &err);
    EXPECT_NE(rc, 0);
    EXPECT_NE(err.code, 0);
    EXPECT_NE(err.message[0], '\0');
}

// A valid DLL that exports no plugin entry points fails cleanly — exercising
// the FreeLibrary-on-failure path (the hardening fix): the just-loaded module
// is unmapped and an error is reported, no crash. (The runtime DLL itself is a
// real library but has no numkit_plugin_register.)
TEST(Plugin, LoadNonPluginDllReportsMissingEntryPoints)
{
    numkit_error err;
    err.code     = 0;
    const int rc = numkit_load_plugin(NUMKIT_RT_SHARED_DLL, &err);
    EXPECT_NE(rc, 0);
    EXPECT_NE(err.code, 0);
    EXPECT_NE(err.message[0], '\0');
}

// ---- Embedding (DESIGN.md §6b) ---------------------------------------------
// numkit_eval runs nk source in the runtime's persistent workspace — the host
// embedding entry point.

TEST(Embed, EvalExpression)
{
    numkit_error err;
    err.code = 0;
    numkit_val r = numkit_eval("3 + 4", &err);
    ASSERT_NE(r, nullptr) << err.message;
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 7.0);
    numkit_release(r);
}

TEST(Embed, EvalStatefulWorkspace)
{
    numkit_release(numkit_eval("numkit_embed_x = 10;", nullptr));  // persist into workspace
    numkit_val r = numkit_eval("numkit_embed_x * 2", nullptr);
    ASSERT_NE(r, nullptr);
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 20.0);
    numkit_release(r);
}

TEST(Embed, EvalArrayResult)
{
    numkit_val r = numkit_eval("sort([3 1 2])", nullptr);
    ASSERT_NE(r, nullptr);
    ASSERT_EQ(numkit_numel(r), 3u);
    double out[3] = {0, 0, 0};
    numkit_unbox_array(r, out, 3);
    EXPECT_DOUBLE_EQ(out[0], 1.0);
    EXPECT_DOUBLE_EQ(out[2], 3.0);
    numkit_release(r);
}

TEST(Embed, EvalErrorTranslated)
{
    numkit_error err;
    err.code = 0;
    numkit_val r = numkit_eval("error('boom from embed')", &err);
    EXPECT_EQ(r, nullptr);
    EXPECT_NE(err.code, 0);
    EXPECT_NE(err.message[0], '\0');
}

// A plugin function is callable from evaluated nk source, not just numkit_call
// — closing the loop: load a plugin, then USE it from a script.
TEST(Embed, EvalCallsPluginFunction)
{
    numkit_error err;
    err.code = 0;
    ASSERT_EQ(numkit_load_plugin(NUMKIT_SAMPLE_PLUGIN_PATH, &err), 0) << err.message;
    numkit_val r = numkit_eval("numkit_sample_triple(5)", &err);
    ASSERT_NE(r, nullptr) << err.message;
    EXPECT_DOUBLE_EQ(numkit_unbox_scalar(r), 15.0);  // 5 * 3
    numkit_release(r);
}

// ---- handle-balance leak check (DESIGN.md §6a) -----------------------------
// Every box/call/eval result must be released; numkit_debug_live_handles returns
// to baseline. The PORTABLE leak check for the bridge's own handle lifecycle
// (MSVC's ASan has no LeakSanitizer). Covers the multi-output extra-release
// path (a regression there would leave the counter > baseline) and errors.
TEST(Leak, HandleBalanceAcrossPaths)
{
    const long long base = numkit_debug_live_handles();

    {  // box + release
        numkit_val x = numkit_box_scalar(2.0);
        numkit_release(x);
    }
    {  // single-output call
        numkit_val a = numkit_box_scalar(0.0);
        numkit_val r = numkit_call("sin", &a, 1, 1, nullptr, nullptr);
        numkit_release(a);
        numkit_release(r);
    }
    {  // multi-output call — exercises the adapter's extra-output release path
        ASSERT_EQ(numkit_register_fn("numkit_bal_divmod", numkit_test_divmod), 0);
        numkit_val   args[2] = {numkit_box_scalar(17.0), numkit_box_scalar(5.0)};
        numkit_val   extra[1] = {nullptr};
        numkit_val   q        = numkit_call("numkit_bal_divmod", args, 2, 2, extra, nullptr);
        numkit_release(args[0]);
        numkit_release(args[1]);
        numkit_release(q);
        numkit_release(extra[0]);
    }
    {  // eval
        numkit_val e = numkit_eval("3 + 4", nullptr);
        numkit_release(e);
    }
    {  // a failed call creates no net handle (release(null) is a no-op)
        numkit_val   a = numkit_box_scalar(1.0);
        numkit_error err;
        err.code = 0;
        numkit_val r = numkit_call("a_fn_that_does_not_exist_zzz", &a, 1, 1, nullptr, &err);
        EXPECT_EQ(r, nullptr);
        numkit_release(a);
        numkit_release(r);
    }

    EXPECT_EQ(numkit_debug_live_handles(), base) << "bridge leaked numkit_val handles";
}
